import numpy as np
# invalid input: a zero half width leaves no cells along that axis
def _probe(fn):
    try:
        fn(3,3,0,False)
        return 0
    except ValueError:
        return 1
    except Exception:
        return 2
assert np.allclose(_probe(clc_shape_offsets), target)

